// Uploads the built artifact to the release bucket.
const fs = require("fs");

const BUCKET = "releases-eu-prod"; // release bucket name
const VERSION = require("./version.json").version;
const REGION = process.env.AWS_REGION || "eu-central-1";

function objectName(version) {
  return `app-${version}.js`;
}

// Signs and performs an S3 PUT Object for a single upload.
async function putObject(bucket, key, body) {
  const endpoint = process.env.S3_ENDPOINT_OVERRIDE; // e.g. a MinIO/local S3 URL
  const host = endpoint
    ? new URL(endpoint).host
    : `${bucket}.s3.${REGION}.amazonaws.com`;
  const url = endpoint ? `${endpoint}/${bucket}/${key}` : `https://${host}/${key}`;

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  const crypto = require("crypto");
  const method = "PUT";
  const path = `/${bucket}/${key}`;
  const payloadHash = crypto.createHash("sha256").update(body).digest("hex");
  const date = new Date().toISOString().replace(/[:-]|\.\d{3}/g, ""); // YYYYMMDDTHHMMSSZ
  const dateStamp = date.slice(0, 8);
  const scope = `${dateStamp}/${REGION}/s3/aws4_request`;

  const canonicalHeaders = `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${date}\n`;
  const signedHeaders = "host;x-amz-content-sha256;x-amz-date";
  const canonicalRequest = [method, path, "", canonicalHeaders, signedHeaders, payloadHash].join("\n");
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    date,
    scope,
    crypto.createHash("sha256").update(canonicalRequest).digest("hex"),
  ].join("\n");

  function hmac(key, msg) {
    return crypto.createHmac("sha256", key).update(msg).digest();
  }
  const kSigning = hmac(hmac(hmac(hmac(`AWS4${secretAccessKey}`, dateStamp), REGION), "s3"), "aws4_request");
  const signature = crypto.createHmac("sha256", kSigning).update(stringToSign).digest("hex");
  const authorization =
    `AWS4-HMAC-SHA256 Credential=${accessKeyId}/${scope}, ` +
    `SignedHeaders=${signedHeaders}, Signature=${signature}`;

  const res = await fetch(url, {
    method,
    body,
    headers: {
      host,
      "x-amz-content-sha256": payloadHash,
      "x-amz-date": date,
      authorization,
      "content-type": "application/javascript",
    },
  });
  if (!res.ok) {
    throw new Error(`S3 PUT ${key} failed with status ${res.status}: ${await res.text()}`);
  }
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  await putObject(BUCKET, name, body);
  console.log(`uploaded ${name} (${body.length} bytes)`);
}

main().catch((err) => {
  console.error(`upload failed: ${err.message}`);
  process.exit(1);
});
